import("./tasks/drone/task.mjs").then(({ random, TASK, TAKEOFF }) => {
  const t0 = performance.now();
  let match = -1;
  const targetSeed = 99999;
  const r0 = random(targetSeed);
  const ox = -TASK.startOffset + 2 * TASK.startOffset * r0();
  const rn0 = random((targetSeed ^ 0xa5a5a5a5) >>> 0);
  const targetX = TAKEOFF.x + ox + (rn0() + rn0() + rn0() - 1.5) * TASK.positionNoise;

  for (let s = 0; s < 1000000; s++) {
    let a = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const u0 = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    const x = -2.1 + (-0.045 + 0.09 * u0);
