          thrust: clamp(thrust, 0, 1),
          roll: clamp(solveAxis('roll', tauRcmd), -0.6, 0.6),
          pitch: clamp(solveAxis('pitch', tauPcmd), -0.6, 0.6),
          yawRate: clamp(shadow.rates.yaw + tauYcmd / (8 * inertia), -2, 2),
        };
