      t = Math.imul(b ^ (b >>> 15), b | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      const n4 = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      b = (b + 0x6d2b79f5) >>> 0;
