        const tauP = inertia * (120 * (pitchDes - shadow.att.pitch) + 22 * (0.5 * dPitchDes - shadow.rates.pitch) - 0.30 * curMp);
        const tauY = inertia * (-8 * shadow.rates.yaw - 20 * shadow.att.yaw);

